package dev.admutium.techmod.client.suit;
import dev.admutium.techmod.suit.*;import dev.admutium.techmod.energy.Energy;import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.Tooltip;import net.minecraft.client.gui.screens.Screen;import net.minecraft.client.input.*;import net.minecraft.network.chat.Component;
/** All active systems on one page; release/open latch prevents native key-repeat flicker. */
public final class SuitRadialScreen extends Screen {
 private int x,y;
 public SuitRadialScreen(){super(Component.literal("Системы костюма"));}
 @Override protected void init(){x=(width-346)/2;y=(height-238)/2;String[] keys={"flight","run","magnet","ore_scan","enemy_scan","cloak","night","light","vein","feed","beacon","warp"};var d=SuitClient.wornData();for(int i=0;i<keys.length;i++){String key=keys[i];int col=i%3,row=i/3;String label=key.equals("flight")?"Полёт: "+SuitClient.flightLabel():Component.translatable("suit.upgrade."+key).getString();var button=new SuitUi.Control(label,x+12+col*110,y+47+row*29,104,25,()->{if(key.equals("flight"))minecraft.setScreenAndShow(new SuitFlightScreen());else{SuitClient.action("toggle",key);}},()->key.equals("flight")?!SuitClient.flightLabel().equals("Выкл"):SuitClient.wornData().on(key));var u=SuitUpgrade.byId(key);button.active=d.level(u)>0;button.setTooltip(Tooltip.create(Component.literal(button.active?SuitDescriptions.detail(u):"Откройте улучшение на станции")));addRenderableWidget(button);}
 var scan=addRenderableWidget(SuitUi.button("Фильтр ресурсов",x+12,y+168,151,20,()->minecraft.setScreenAndShow(new SuitOreScreen(this))));scan.active=d.level(SuitUpgrade.ORE_SCAN)>0;
 var range=addRenderableWidget(SuitUi.button("Радиус магнита: "+Math.min(d.magnetRange(),d.level(SuitUpgrade.MAGNET))+" м",x+173,y+168,161,20,()->{SuitClient.action("magnet_range",Integer.toString((SuitClient.wornData().magnetRange()+1)%4));}));range.active=d.level(SuitUpgrade.MAGNET)>0;
 addRenderableWidget(SuitUi.button("Притянуть [V]",x+12,y+195,151,20,()->SuitClient.action("toggle","magnet_pulse"))).active=d.level(SuitUpgrade.MAGNET)>0;
 addRenderableWidget(SuitUi.button("Вернуться",x+173,y+195,161,20,this::onClose));}
 @Override public void tick(){for(var child:children())if(child instanceof SuitUi.Control b&&b.getMessage().getString().startsWith("Радиус магнита:"))b.setMessage(Component.literal("Радиус магнита: "+Math.min(SuitClient.wornData().magnetRange(),SuitClient.wornData().level(SuitUpgrade.MAGNET))+" м"));}
 @Override public void extractRenderState(GuiGraphicsExtractor g,int mx,int my,float dt){SuitUi.panel(g,x,y,346,238);g.text(font,"КОНТУР / СИСТЕМЫ",x+12,y+12,SuitUi.ACCENT);var d=SuitClient.wornData();g.text(font,Energy.format(d.energy())+" / "+Energy.format(d.capacity())+" ТЕ",x+12,y+27,SuitUi.TEXT);String rate="Расход: "+Energy.format(java.util.Arrays.stream(SuitClient.rates).sum(),true)+" ТЕ/с";g.text(font,rate,x+334-font.width(rate),y+27,SuitUi.MUTED);super.extractRenderState(g,mx,my,dt);String hint="Спринт: "+minecraft.options.keySprint.getTranslatedKeyMessage().getString()+" · ESC — закрыть";g.text(font,hint,x+12,y+223,SuitUi.MUTED);}
 @Override public boolean keyPressed(KeyEvent e){if(SuitClient.menuKey.matches(e)){onClose();return true;}return super.keyPressed(e);}
 @Override public boolean isPauseScreen(){return false;}
}
